version.transform:
(
  $data := $ 
    ~> | $ | {
      "category": $moment(creditedAt).format("MM/DD/YYYY")
    } |;

  $groupedData := ($data{
    category: {
      "category": $first(category),
      "utilization": $sum(utilizationTime[$not($isNil($))]) / 3600,
      "uptime": $sum(productionTime[$not($isNil($))]) / 3600
    }
  } ~> $values)^(category);

  $avg := $round($average($groupedData.($coalesce([utilization, uptime]))), 1);

  $utilizationCount := $count($groupedData[$not($isNil(utilization))]);

  {
    "chart": {
      "subcaption": $utilizationCount = 0
          ? 'Based on Workcenter Status'
        : $utilizationCount = $count($groupedData)
          ? 'Based on Extruder Pressure'
        : 'Based on Workcenter Status & Extruder Pressure',
      "numberSuffix": "h"
    },
    "categories": [
        {
            "category": [$groupedData.{
              "label": category,
              "toolText": category & "; " & (
                $isNil(utilization)
                  ? 'Based on Workcenter Status'
                  : 'Based on Extruder Pressure'
              )
            }]
        }
    ],
    "dataSet": [
        {
            "data": [$groupedData.{
              "value": $coalesce([utilization, uptime])
            }]
        }
    ],
    "trendlines": [
      {
        "line": [
          {
            "startvalue": 20.4,
            "color": "#43a047",
            "displayvalue": "85%",
            "valueOnRight": true
          },
          {
            "startvalue": 21.6,
            "color": "#ffa000",
            "displayvalue": "90%",
            "valueOnRight": true
          },
          {
            "startvalue": 24,
            "color": "#f44336",
            "displayvalue": "100%",
            "valueOnRight": true
          },
          {
            "startvalue": $avg,
            "color": "#006fba",
            "displayvalue": "Avg: " & $string($avg),
            "valueOnRight": true
          }
        ]
      }
    ]
  }
)
